\set ON_ERROR_STOP on
-- Requires a DISPOSABLE TEST database. Existing echo_core -> abort safely.
-- All DDL and fixture changes roll back, including a failure with ON_ERROR_STOP.
BEGIN;
\ir schema.sql
\ir fixtures.sql
CREATE TEMP TABLE check_results (label text PRIMARY KEY, result text NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.expect_error(label text, statement text, expected text)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text := NULL;
BEGIN
    BEGIN
        EXECUTE statement;
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS got = RETURNED_SQLSTATE;
    END;
    IF got IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'FAIL %: expected SQLSTATE %, got %', label, expected, COALESCE(got,'SUCCESS');
    END IF;
    INSERT INTO check_results VALUES(label,'SAT');
END $$;
CREATE FUNCTION pg_temp.expect_true(label text, ok boolean)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %', label; END IF;
    INSERT INTO check_results VALUES(label,'SAT');
END $$;

